#pragma once
#include "FxPage.h"
#include "SequencerPage.h"
#include "KeyboardPanel.h"
#include <iostream>
namespace noctrl {
// Offline render gallery for visual review; never edits the user's libraries or saved sound.
inline int renderStyleAudit(){using namespace juce;auto owner=std::make_unique<SynthProcessor>();auto& p=*owner;p.prepareToPlay(48000,512);p.loadPreset(0);auto output=File::getCurrentWorkingDirectory().getChildFile("Reports/StyleAudit");output.createDirectory();auto save=[&](Component& c,String name){auto stream=output.getChildFile(name+".png").createOutputStream();if(!stream)return false;stream->setPosition(0);stream->truncate();return PNGImageFormat().writeImageToStream(c.createComponentSnapshot(c.getLocalBounds()),*stream);};std::unique_ptr<AudioProcessorEditor> editor(p.createEditor());for(auto page:{String("OSC"),String("MIX"),String("FX"),String("MATRIX"),String("PACKS")}){for(auto* child:editor->getChildren())if(auto* button=dynamic_cast<TextButton*>(child))if(button->getButtonText()==page&&button->onClick)button->onClick();if(!save(*editor,page))return 1;}for(auto* child:editor->getChildren())if(auto* keyboard=dynamic_cast<KeyboardPanel*>(child)){keyboard->onSequenceRequested(false);if(!save(*editor,"CLIP"))return 2;keyboard->onSequenceRequested(true);if(!save(*editor,"ARP"))return 3;}OscParameterPanel params(p,0,"OSC A / ADVANCED",{"phase","rand","voices","detune"});if(!save(params,"OSC-Parameters"))return 4;OscRemapPanel remap(p,0,0);if(!save(remap,"OSC-Remap"))return 5;OscModernTheme theme;for(int type=0;type<(int)fxDefinitions().size();++type){int slot=p.addFx(0,type);if(slot<0)return 6;auto rack=p.rack();for(auto& entry:rack->entries)if(entry.slot==slot){FxRow row(p,entry);row.setLookAndFeel(&theme);theme.attach(row);row.setSize(934,FxRow::preferredHeight(type));bool ok=save(row,"FX-"+String(type)+"-"+File::createLegalFileName(fxDefinitions()[(size_t)type].name));p.set(fxId(slot,"enabled"),0);row.refreshVisual();ok=ok&&save(row,"FX-"+String(type)+"-"+File::createLegalFileName(fxDefinitions()[(size_t)type].name)+"-Bypassed");p.set(fxId(slot,"enabled"),1);row.setLookAndFeel(nullptr);if(!ok)return 7;break;}}std::cout<<"PASS: rendered all seven plugin pages and oscillator editors plus all FX modules to Reports/StyleAudit\n";return 0;}
}
